package ports

import (
	"fmt"
	"os"
	"runtime"
	"sync/atomic"
	"testing"

	gproc "github.com/shirou/gopsutil/v4/process"
)

// What the package asks of the host about processes goes through these seams,
// so a test can substitute them (DEVDESK-708). They are written only by tests
// of this package, never while a Cmd runs.
var (
	selfPID           = os.Getpid
	parentPID         = os.Getppid
	goos              = runtime.GOOS
	procOS    osProcs = realOS{}
)

// osProcs is everything this package asks the operating system about a single
// process: when it was created, and to end it.
type osProcs interface {
	// createTime is the creation time in ms since the epoch. It is opaque: it
	// is only compared with another value of the same function.
	createTime(pid int) (int64, error)
	// kill is SIGKILL, or TerminateProcess on Windows.
	kill(pid int) error
}

// realOS is the production osProcs.
type realOS struct{}

func (realOS) createTime(pid int) (int64, error) {
	p, err := gproc.NewProcess(int32(pid)) //nolint:gosec // a PID fits in int32 on every supported OS
	if err != nil {
		return 0, err
	}
	return p.CreateTime()
}

// kill is the only place of this package that signals a process, and its first
// statement is the run-time guard (TestOnlyRealOSSendsASignal).
func (realOS) kill(pid int) error {
	refuseRealSignalUnderTest(pid)
	p, err := os.FindProcess(pid)
	if err != nil {
		return fmt.Errorf("finding the process: %w", err)
	}
	return p.Kill()
}

// realSignalsAllowed is flipped only by allowRealSignals(t) in the _test.go
// files of this package.
var realSignalsAllowed atomic.Bool

// refuseRealSignalUnderTest panics in a test binary that did not allow real
// signals. It panics rather than returning an error: an error would be shown as
// an ordinary failed kill and the test could pass, leaving the guard silent.
func refuseRealSignalUnderTest(pid int) {
	if testing.Testing() && !realSignalsAllowed.Load() {
		panic(fmt.Sprintf("ports: a test reached a real signal to PID %d without a substituted procOS; "+
			"replace procOS, or call allowRealSignals(t) for a child the test started "+
			"(DEVDESK-708, docs/architecture/network.md)", pid))
	}
}
package ports

import (
	"fmt"
	"strconv"
)

// Protection says why DevDesk refuses to signal a process, or that it does not
// (DEVDESK-708). The zero value is Unprotected, so a Protection nobody set
// never blocks anything.
type Protection int

const (
	// Unprotected is a process DevDesk may signal.
	Unprotected Protection = iota
	// ProtectedSelf is DevDesk's own process.
	ProtectedSelf
	// ProtectedInit is PID 1.
	ProtectedInit
	// ProtectedWindowsSystem is PID 0 or 4 on Windows (Idle and System).
	ProtectedWindowsSystem
	// ProtectedParent is the process that started DevDesk: the direct parent
	// only, never a grandparent.
	ProtectedParent
)

// The sentences shown to the user for each refusal.
const (
	ReasonSelf          = "This is DevDesk itself"
	ReasonParent        = "This process started DevDesk"
	ReasonInit          = "PID 1 is the system's init process"
	ReasonWindowsSystem = "Windows system process"
)

// Reason is the sentence to show for p, or "" for Unprotected.
func (p Protection) Reason() string {
	switch p {
	case ProtectedSelf:
		return ReasonSelf
	case ProtectedParent:
		return ReasonParent
	case ProtectedInit:
		return ReasonInit
	case ProtectedWindowsSystem:
		return ReasonWindowsSystem
	default:
		return ""
	}
}

// hostView is what protectionFor needs to know about the host. parentBornFirst
// is a function so the creation time, which costs a system call, is read only
// when the PID asked about is the parent's.
type hostView struct {
	self, parent    int
	windows         bool
	parentBornFirst func() bool
}

// protectionFor is the rule, free of any system call. The order matters when
// one PID qualifies twice: DevDesk itself first, then PID 1 (also a parent
// inside a container), then the Windows system PIDs, then the parent. A parent
// PID of 0 means unknown (the parent lives outside this PID namespace) and
// never matches.
func protectionFor(pid int, h hostView) Protection {
	switch {
	case pid == h.self:
		return ProtectedSelf
	case pid == 1:
		return ProtectedInit
	case h.windows && (pid == 0 || pid == 4):
		return ProtectedWindowsSystem
	case h.parent > 0 && pid == h.parent && h.parentBornFirst():
		return ProtectedParent
	default:
		return Unprotected
	}
}

// parentStartedFirst reports whether parent was created no later than self. A
// parent born after DevDesk is a process that reused the PID of the real one,
// which exited. Anything unreadable, and a tie, counts as true: when in doubt
// the parent is protected.
func parentStartedFirst(parent, self int) bool {
	parentCreated, err := procOS.createTime(parent)
	if err != nil {
		return true
	}
	selfCreated, err := procOS.createTime(self)
	if err != nil {
		return true
	}
	return parentCreated <= selfCreated
}

// protectionOf feeds protectionFor from the seams.
func protectionOf(n int) Protection {
	self, parent := selfPID(), parentPID()
	return protectionFor(n, hostView{
		self:            self,
		parent:          parent,
		windows:         goos == "windows",
		parentBornFirst: func() bool { return parentStartedFirst(parent, self) },
	})
}

// ProtectionOf says whether DevDesk refuses to signal the process pid. An empty
// or non-numeric pid is Unprotected: it names no process, so there is nothing
// to protect. It runs on every render, hence the lazy creation-time read.
func ProtectionOf(pid string) Protection {
	n, err := strconv.Atoi(pid)
	if err != nil {
		return Unprotected
	}
	return protectionOf(n)
}

// ProtectedError is the refusal Kill returns for a protected process. It is
// not an operating system error: it does not wrap os.ErrPermission.
type ProtectedError struct {
	PID        int
	Protection Protection
}

func (e *ProtectedError) Error() string {
	return fmt.Sprintf("PID %d not stopped: %s", e.PID, e.Protection.Reason())
}

package ports

import (
	"testing"
)

// Helpers for the tests of this package that reach the process seams
// (DEVDESK-708). The seams are package-level variables, so no test in this
// package may call t.Parallel: two tests swapping them would see each other.

// fakeOS is a substitute osProcs. It records every PID it was asked to kill and
// never signals anything.
type fakeOS struct {
	created   map[int]int64 // creation time per PID, in ms; opaque
	createErr map[int]error // a read error per PID
	killErr   error         // returned by every kill
	kills     []int         // PIDs kill was called with, in order
}

func (f *fakeOS) createTime(pid int) (int64, error) {
	if err, ok := f.createErr[pid]; ok {
		return 0, err
	}
	return f.created[pid], nil
}

func (f *fakeOS) kill(pid int) error {
	f.kills = append(f.kills, pid)
	return f.killErr
}

// useFakeOS replaces the four seams (selfPID, parentPID, goos, procOS) and
// restores them when the test ends.
func useFakeOS(t *testing.T, self, parent int, goosName string) *fakeOS {
	t.Helper()
	oldSelf, oldParent, oldGOOS, oldProc := selfPID, parentPID, goos, procOS
	t.Cleanup(func() {
		selfPID, parentPID, goos, procOS = oldSelf, oldParent, oldGOOS, oldProc
	})

	fake := &fakeOS{
		created:   map[int]int64{},
		createErr: map[int]error{},
	}
	selfPID = func() int { return self }
	parentPID = func() int { return parent }
	goos = goosName
	procOS = fake
	return fake
}

// allowRealSignals lets realOS.kill send a real signal for the rest of this
// test. Only a test that signals a child it started itself may call it; never
// one that aims at any other PID.
func allowRealSignals(t *testing.T) {
	t.Helper()
	realSignalsAllowed.Store(true)
	t.Cleanup(func() { realSignalsAllowed.Store(false) })
}
